const accent=value=>Math.max(0,Math.min(1.3,Number(value)||0));
const hash=(seed,n)=>{let x=(seed^Math.imul(n+1,2654435761))>>>0;x=Math.imul(x^(x>>>16),2246822507);return (x^(x>>>13))>>>0;};
const stages=['introduce','answer','vary','return'];

// Remember a two-bar idea by its seed and score address, not by mutable
// playback history. A seek can reconstruct the same question and answer.
// The motif is generated by UPIC; these addresses never select source MIDI.
export function phraseDevelopment(seed,bar,options={}){
 const position=Math.max(0,Math.floor(Number(bar)||0)),within=position%8;
 const cycle=Math.floor(position/8),stage=stages[Math.floor(within/2)];
 const variation=Math.max(0,Math.min(65535,Math.round(Number(options.phraseVariation)||0)));
 const motifId=hash(seed,variation+813).toString(16).padStart(8,'0');
 return {
  motifId,cycle,stage,bar:within,
  // Return to the original material after one contrasting two-bar idea.
  // Only the variation changes its source address between cycles.
  sourceBar:stage==='vary'?2+(cycle%4)*2+within%2:within%2,
  role:stage==='answer'?'answer':stage==='vary'?'development':'theme',
  leadGain:stage==='answer'?.88:stage==='return'?.94:stage==='vary'?.96:1,
  supportGain:stage==='answer'?.78:stage==='vary'?.88:1,
  answerDelay:stage==='answer'?.25+.25*(hash(seed,variation+817)%2):0,
  cadenceBeat:within===3?2.5:within===7?2:null,
 };
}

// Leave the answer a little later, with room between its notes. The return
// uses the original timing, so recognition survives changes in harmony.
export function developPhraseEvents(events,development){
 const delay=development.answerDelay;
 return events.map((event,index)=>({
  ...event,beat:event.beat+delay,
  duration:event.duration*(development.stage==='answer'?.9:1),
  accent:accent(event.accent)*development.leadGain,
  motifNote:index,
 })).filter(event=>event.beat<3.96&&(development.cadenceBeat===null||event.beat<development.cadenceBeat));
}
